import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"File System Abstraction","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/file-system.md","filePath":"en/deep-dive/file-system.md","lastUpdated":1787300168000}`),a={name:`deep-dive/file-system.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="file-system-abstraction" tabindex="-1">File System Abstraction <a class="header-anchor" href="#file-system-abstraction" aria-label="Permalink to “File System Abstraction”">​</a></h1><p>The plugin abstracts the file system interfaces into unified file system class <code>RootFs</code> as defined in <code>packages/plugin/src/fs/interface.ts</code>. All abstractions are designed to be immutable and throw-away in each sync run.</p><p>Different types of <a href="./file-system-wrappers">wrappers</a> can be applied above the unified interface. Their existence allows easy extensibility of file system functions. Raw FS classes should not carry any additional functions, such as base dir config or retry, they should all be achieved via wrappers.</p><h2 id="vault-abstraction" tabindex="-1">Vault Abstraction <a class="header-anchor" href="#vault-abstraction" aria-label="Permalink to “Vault Abstraction”">​</a></h2><p>Vault file system consumes <a href="./request#vault-request"><code>VaultRequest</code></a>, a typed operation function abstracting Obsidian vault APIs.</p><p><code>constructor()</code>: receives a <code>VaultRequest</code> and the vault name.</p><p><code>getUid()</code>: returns <code>obsidian-vault~&lt;vault-name&gt;</code>.</p><p><code>read()</code>: delegates to <code>VaultRequest</code> <code>GET</code>, which wraps <code>vault.adapter.readBinary()</code> and converts the result to <code>Binary</code>.</p><p><code>readStream()</code>: delegates to <code>GET_STREAM</code>, which fetches <code>vault.adapter.getResourcePath(path)</code> and returns the response body. It throws if no response body is available.</p><p><code>write()</code>: delegates to <code>PUT</code>, then calls <code>this.stat()</code> and returns the file UID.</p><p><code>writeStream()</code>:</p><ul><li>creates <code>.trash/&lt;random-UUID&gt;.part</code>, creating <code>.trash</code> when needed</li><li>reads the input stream and appends each chunk with <code>APPEND</code></li><li>removes an existing destination, then moves the temporary file into place</li><li>calls <code>this.stat()</code> and returns the file UID</li><li>on failure, cancels the input stream and permanently removes the temporary file</li></ul><p><code>delete()</code>: delegates to <code>DELETE</code>. Permanent deletes and <code>vault.config.trashOption: &quot;none&quot;</code> call <code>vault.adapter.remove()</code>. <code>&quot;local&quot;</code> calls <code>trashLocal()</code> directly; <code>&quot;system&quot;</code> or an unset option tries <code>trashSystem()</code> and falls back to <code>trashLocal()</code> when needed.</p><p><code>move()</code>: delegates to <code>MOVE</code>, wrapping <code>vault.adapter.rename()</code> after normalizing the destination path.</p><p><code>mkdir()</code>: delegates to <code>MKDIR</code>, wrapping <code>vault.adapter.mkdir()</code>. Creating the root is a no-op.</p><p><code>stat()</code>:</p><ul><li>delegates to <code>STAT</code></li><li>uses cached <code>TFile</code>/<code>TFolder</code> metadata when <code>workspace.layoutReady</code>; otherwise falls back to <code>vault.adapter.stat()</code></li><li>converts file results to the project <code>Stat</code> format, with <code>uid</code> as <code>mtime</code> + <code>size</code> separated by <code>~</code>; folders have no UID</li></ul><p><code>list()</code>: recursively traverses descendants with concurrent requests. <code>LIST</code> uses cached folder children when the layout is ready, otherwise <code>vault.adapter.list()</code>. Each file is then passed through <code>stat()</code>, while folder entries are returned directly. The queried root is excluded from the result.</p><p><code>exists()</code>: checks <code>vault.getAbstractFileByPath()</code> first, then falls back to <code>vault.adapter.exists(path, true)</code>.</p><h2 id="unified-key-schema" tabindex="-1">Unified Key Schema <a class="header-anchor" href="#unified-key-schema" aria-label="Permalink to “Unified Key Schema”">​</a></h2><p>All abstracted file systems should automatically convert between the unified key and their native file path:</p><ul><li><code>/</code> is the root.</li><li>Files have no trailing slash.</li><li>Folders have a trailing slash.</li><li>Non-root paths do not have leading slash</li></ul><p>For example:</p><ul><li>root: <code>/</code></li><li><code>file.md</code>, <code>folder/file.md</code> stand for files.</li><li><code>folder/</code>, <code>folder/folder/</code> stand for folders.</li></ul><h2 id="optimizer" tabindex="-1">Optimizer <a class="header-anchor" href="#optimizer" aria-label="Permalink to “Optimizer”">​</a></h2><p>During execution, local and remote file systems use optimization wrappers. They batch mutation calls and invoke the first registered optimizer; batching, companion reads, and dependency handling are documented in the <a href="./file-system-wrappers#optimization-wrapper">optimization wrapper</a>.</p><p>The routine sorts tasks into file removals, directory creation, moves, directory removals, and remaining operations. It then executes the optimized task list concurrently. The run reports <code>completed</code>, <code>failed</code>, <code>cancelled</code>, or <code>noop</code>.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};